    },
    {
      "claim": "The earlier high prediction rested on vinorelbine (F 25–43%) and naldemedine (F 20–56%), which are structurally unrelated to this ergopeptine and have low transferability to the query.",
      "card_ids": ["C03", "C18", "C02", "C23"]
    },
    {
      "claim": "The DHE MAP0004 oral AUC ratio (~39% vs IV) reflects a specialized formulation and is not a conventional oral bioavailability measurement; it does not outweigh the related low-exposure ergot-alkaloid records.",
      "card_ids": ["C27"]
    }
  ],
  "new_evidence_assessment": [
